import {on} from 'delegated-events'

on('submit', '.js-copilot-policy-select-orgs-form', function (event) {
  const form = event.currentTarget as HTMLFormElement
  const checkboxes = form.querySelectorAll<HTMLInputElement>('.js-copilot-policy-org-checkbox')

  const newlyEnabled: string[] = []
  const newlyDisabled: string[] = []

  for (const checkbox of checkboxes) {
    const wasChecked = checkbox.hasAttribute('data-initially-checked')
    const isChecked = checkbox.checked

    if (isChecked && !wasChecked) {
      newlyEnabled.push(checkbox.value)
    } else if (!isChecked && wasChecked) {
      newlyDisabled.push(checkbox.value)
    }

    // Remove name so original checkboxes don't submit
    checkbox.removeAttribute('name')
  }

  for (const id of newlyEnabled) {
    const input = document.createElement('input')
    input.type = 'hidden'
    input.name = 'newly_enabled_organization_ids[]'
    input.value = id
    form.appendChild(input)
  }

  for (const id of newlyDisabled) {
    const input = document.createElement('input')
    input.type = 'hidden'
    input.name = 'newly_disabled_organization_ids[]'
    input.value = id
    form.appendChild(input)
  }
})
