/**
 * Shared utility functions for the MCP registry module.
 */

/**
 * Extracts an embedded server JSON string from a URL's query parameters.
 * Looks for `server_json` or `serverJson` params.
 */
export function getEmbeddedServerJsonFromUrl(urlValue: string): string | null {
  try {
    const parsedUrl = new URL(urlValue, window.location.origin)
    const embedded = parsedUrl.searchParams.get('server_json') || parsedUrl.searchParams.get('serverJson')
    return embedded?.trim() || null
  } catch {
    return null
  }
}
