import {on} from 'delegated-events'
import {PANEL_IDS} from './types'
import {
  buildServerDetailFromForm,
  buildServerDetailFromJson,
  validateServerDetail,
  applyServerDetailToForm,
  serializeServerDetail,
  getFirstValidationError,
} from './server-detail'
import {getEmbeddedServerJsonFromUrl} from './utils'

type PrivateServerValidationStatus = {
  scheme: 'success' | 'warning'
  message: string
}

type PrivateServerUrlFetchState = {
  state: 'idle' | 'loading' | 'success' | 'error'
  message?: string
}

type PrivateServerSchemaInput = HTMLInputElement | HTMLTextAreaElement

const privateServerUrlFetchControllers = new WeakMap<HTMLFormElement, AbortController>()
const privateServerUrlFetchState = new WeakMap<HTMLFormElement, PrivateServerUrlFetchState>()
const privateServerUrlInputTimers = new WeakMap<HTMLFormElement, ReturnType<typeof setTimeout>>()

function getPrivateServerFieldInputs(form: HTMLFormElement): {
  rootFieldInputs: PrivateServerSchemaInput[]
  rawJsonInput: HTMLTextAreaElement | null
  jsonUrlInput: HTMLInputElement | null
} {
  return {
    rootFieldInputs: Array.from(form.querySelectorAll<PrivateServerSchemaInput>('[data-private-server-root-field]')),
    rawJsonInput: form.querySelector<HTMLTextAreaElement>('textarea[name="private_server[raw_json]"]'),
    jsonUrlInput: form.querySelector<HTMLInputElement>('input[name="private_server[json_url]"]'),
  }
}

function writeRawJsonFromFormState(form: HTMLFormElement): void {
  const {rawJsonInput} = getPrivateServerFieldInputs(form)
  if (!rawJsonInput) return

  // Start from existing raw JSON to preserve fields not represented in form (packages, remotes, advanced)
  let existing: Record<string, unknown> = {}
  if (rawJsonInput.value.trim().length > 0) {
    try {
      const parsed = JSON.parse(rawJsonInput.value)
      if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
        existing = parsed as Record<string, unknown>
      }
    } catch {
      // If existing JSON is invalid, start fresh
    }
  }

  const detail = buildServerDetailFromForm(form)
  // Default version when only name is provided
  if (detail.name && detail.name.length > 0 && (!detail.version || detail.version.length === 0)) {
    detail.version = '1.0.0'
  }

  // Merge form-driven fields over existing JSON (preserves anything not in the form)
  const merged = {...existing, ...detail}

  // If form has package/remote list containers but no entries, remove stale data from existing
  if (!detail.packages && form.querySelector('[data-private-server-packages-list]')) {
    delete merged.packages
  }
  if (!detail.remotes && form.querySelector('[data-private-server-remotes-list]')) {
    delete merged.remotes
  }

  rawJsonInput.value = serializeServerDetail(merged)
}

function writeFormStateFromRawJson(form: HTMLFormElement): void {
  const {rawJsonInput} = getPrivateServerFieldInputs(form)
  if (!rawJsonInput) return

  const detail = buildServerDetailFromJson(rawJsonInput.value)
  if (!detail) return

  applyServerDetailToForm(form, detail)
}

function getPrivateServerUrlPreviewElements(form: HTMLFormElement): {
  previewContainer: HTMLElement | null
  nameElement: HTMLElement | null
} {
  return {
    previewContainer: form.querySelector<HTMLElement>('[data-private-server-url-name-preview]'),
    nameElement: form.querySelector<HTMLElement>('[data-private-server-url-name]'),
  }
}

function setPrivateServerUrlNamePreview(form: HTMLFormElement, serverName: string | null): void {
  const {previewContainer, nameElement} = getPrivateServerUrlPreviewElements(form)
  if (!previewContainer || !nameElement) return

  if (serverName && serverName.trim().length > 0) {
    nameElement.textContent = serverName
    previewContainer.hidden = false
    return
  }

  nameElement.textContent = ''
  previewContainer.hidden = true
}

function clearPrivateServerJsonUrl(form: HTMLFormElement): void {
  const {jsonUrlInput} = getPrivateServerFieldInputs(form)
  if (jsonUrlInput && jsonUrlInput.value.length > 0) {
    jsonUrlInput.value = ''
    setPrivateServerUrlNamePreview(form, null)
    setPrivateServerUrlFetchState(form, {state: 'idle'})
    privateServerUrlFetchControllers.get(form)?.abort()
  }
}

function getEmbeddedServerObjectFromUrl(urlValue: string): Record<string, unknown> | null {
  const embedded = getEmbeddedServerJsonFromUrl(urlValue)
  if (!embedded) return null

  try {
    const parsed = JSON.parse(embedded)
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return null
    return parsed as Record<string, unknown>
  } catch {
    return null
  }
}

function getPrivateServerUrlFetchState(form: HTMLFormElement): PrivateServerUrlFetchState {
  return privateServerUrlFetchState.get(form) || {state: 'idle'}
}

function setPrivateServerUrlFetchState(form: HTMLFormElement, state: PrivateServerUrlFetchState): void {
  privateServerUrlFetchState.set(form, state)
}

function normalizePrivateServerPayloadFromFetchedJson(parsed: unknown): Record<string, unknown> | null {
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return null

  const topLevel = parsed as Record<string, unknown>
  // Support both flat server JSON and wrapped { server: {...} } format
  const serverCandidate =
    topLevel.server && typeof topLevel.server === 'object' && !Array.isArray(topLevel.server)
      ? (topLevel.server as Record<string, unknown>)
      : topLevel

  const name = typeof serverCandidate.name === 'string' ? serverCandidate.name.trim() : ''
  if (name.length === 0) return null

  // Return the full server object; default version if missing
  const result = {...serverCandidate}
  if (typeof result.version !== 'string' || result.version.trim().length === 0) {
    result.version = '1.0.0'
  }

  return result
}

async function fetchPrivateServerPayloadFromUrl(
  urlValue: string,
  signal: AbortSignal,
  form: HTMLFormElement,
): Promise<Record<string, unknown> | null> {
  const proxyPath = form.getAttribute('data-fetch-server-json-path')

  let fetchUrl: string
  let fetchInit: RequestInit

  if (proxyPath) {
    // Use server-side proxy to avoid CSP connect-src restrictions.
    fetchUrl = `${proxyPath}?url=${encodeURIComponent(urlValue)}`
    fetchInit = {method: 'GET', headers: {Accept: 'application/json'}, signal}
  } else {
    // Fallback to direct fetch (only works if CSP allows the target).
    fetchUrl = urlValue
    fetchInit = {method: 'GET', headers: {Accept: 'application/json'}, signal}
  }

  const response = await fetch(fetchUrl, fetchInit)

  if (!response.ok) {
    return null
  }

  const parsed = await response.json()
  return normalizePrivateServerPayloadFromFetchedJson(parsed)
}

function getPrivateServerUrlFetchFailureMessage(): string {
  // eslint-disable-next-line i18n-text/no-en
  return 'Not ready: unable to load server JSON'
}

async function syncPrivateServerFromJsonUrl(form: HTMLFormElement): Promise<void> {
  const {rawJsonInput, jsonUrlInput} = getPrivateServerFieldInputs(form)
  if (!jsonUrlInput || !rawJsonInput) return

  const urlValue = jsonUrlInput.value.trim()
  if (urlValue.length === 0) {
    setPrivateServerUrlNamePreview(form, null)
    setPrivateServerUrlFetchState(form, {state: 'idle'})
    return
  }

  const urlValidationError = validatePrivateServerJsonUrl(urlValue)
  if (urlValidationError) {
    setPrivateServerUrlNamePreview(form, null)
    setPrivateServerUrlFetchState(form, {
      state: 'error',
      message: getFriendlyPrivateServerUrlValidationMessage(urlValidationError),
    })
    return
  }

  const embeddedServerObject = getEmbeddedServerObjectFromUrl(urlValue)
  const embeddedName = typeof embeddedServerObject?.name === 'string' ? embeddedServerObject.name : null
  setPrivateServerUrlNamePreview(form, embeddedName)

  const embeddedServerJson = getEmbeddedServerJsonFromUrl(urlValue)
  if (embeddedServerJson) {
    rawJsonInput.value = embeddedServerJson
    writeFormStateFromRawJson(form)
    setPrivateServerUrlFetchState(form, {state: 'success'})
    return
  }

  privateServerUrlFetchControllers.get(form)?.abort()
  const controller = new AbortController()
  privateServerUrlFetchControllers.set(form, controller)

  setPrivateServerUrlFetchState(form, {state: 'loading'})

  try {
    const payload = await fetchPrivateServerPayloadFromUrl(urlValue, controller.signal, form)
    if (!payload) {
      setPrivateServerUrlNamePreview(form, null)
      setPrivateServerUrlFetchState(form, {
        state: 'error',
        message: getPrivateServerUrlFetchFailureMessage(),
      })
      return
    }

    rawJsonInput.value = JSON.stringify(payload, null, 2)
    writeFormStateFromRawJson(form)

    const payloadName = typeof payload.name === 'string' ? payload.name : null
    setPrivateServerUrlNamePreview(form, payloadName)
    setPrivateServerUrlFetchState(form, {state: 'success'})
  } catch {
    if (controller.signal.aborted) return

    setPrivateServerUrlNamePreview(form, null)
    setPrivateServerUrlFetchState(form, {
      state: 'error',
      message: getPrivateServerUrlFetchFailureMessage(),
    })
  }
}

function getPrivateServerFooterStatusElement(form: Element): HTMLElement | null {
  const formId = form.getAttribute('id')
  if (!formId) return null

  return document.querySelector<HTMLElement>(
    `[data-private-server-validation-status][data-private-server-form-id="${formId}"]`,
  )
}

function setPrivateServerValidationStatus(form: Element, status: PrivateServerValidationStatus | null): void {
  const statusElement = getPrivateServerFooterStatusElement(form)
  if (!statusElement) return

  const successIcon = statusElement.querySelector<HTMLElement>('[data-private-server-validation-icon-success]')
  const warningIcon = statusElement.querySelector<HTMLElement>('[data-private-server-validation-icon-warning]')
  const textElement = statusElement.querySelector<HTMLElement>('[data-private-server-validation-text]')
  if (!textElement) return

  if (!status) {
    textElement.textContent = ''
    statusElement.hidden = true
    if (successIcon) successIcon.hidden = true
    if (warningIcon) warningIcon.hidden = true
    return
  }

  textElement.textContent = status.message
  statusElement.hidden = false
  if (successIcon) successIcon.hidden = status.scheme !== 'success'
  if (warningIcon) warningIcon.hidden = status.scheme !== 'warning'
}

function setPrivateServerSubmitDisabled(form: HTMLFormElement, disabled: boolean): void {
  const formId = form.getAttribute('id')
  if (!formId) return

  const saveButton = document.querySelector<HTMLButtonElement>(
    `[data-private-server-save-button][data-private-server-form-id="${formId}"]`,
  )
  if (!saveButton) return

  saveButton.disabled = disabled
}

function validatePrivateServerRawJsonForUI(jsonValue: string): string | null {
  const detail = buildServerDetailFromJson(jsonValue)
  if (!detail) {
    // eslint-disable-next-line i18n-text/no-en
    return 'Not ready: invalid JSON'
  }

  const result = validateServerDetail(detail)
  const firstError = getFirstValidationError(result)
  if (firstError) {
    // eslint-disable-next-line i18n-text/no-en
    return `Not ready: ${firstError}`
  }

  return null
}

function validatePrivateServerJsonUrl(
  urlValue: string,
): 'invalid_url' | 'https_required' | 'invalid_embedded_server_json' | null {
  if (!/^[a-zA-Z][a-zA-Z\d+.-]*:/.test(urlValue)) {
    return 'invalid_url'
  }

  let parsedUrl: URL
  try {
    parsedUrl = new URL(urlValue, window.location.origin)
  } catch {
    return 'invalid_url'
  }

  if (parsedUrl.protocol !== 'https:') {
    return 'https_required'
  }

  const embeddedServerJson = getEmbeddedServerJsonFromUrl(urlValue)
  if (!embeddedServerJson) return null

  const embeddedError = validatePrivateServerRawJsonForUI(embeddedServerJson)
  if (embeddedError) {
    return 'invalid_embedded_server_json'
  }

  return null
}

function getFriendlyPrivateServerUrlValidationMessage(
  validationCode: 'invalid_url' | 'https_required' | 'invalid_embedded_server_json',
): string {
  // eslint-disable-next-line i18n-text/no-en
  if (validationCode === 'invalid_url') return 'Not ready: invalid URL'

  // eslint-disable-next-line i18n-text/no-en
  if (validationCode === 'https_required') return 'Not ready: URL must use HTTPS'

  // eslint-disable-next-line i18n-text/no-en
  return 'Not ready: invalid embedded server JSON'
}

function getPrivateServerValidationStatus(form: HTMLFormElement): PrivateServerValidationStatus | null {
  const dialogBody = form.closest('[data-view-component]')
  const inputMode =
    form.querySelector<HTMLInputElement>('.js-private-server-input-mode') ||
    dialogBody?.querySelector<HTMLInputElement>('.js-private-server-input-mode') ||
    null
  if (!inputMode) return null

  if (inputMode.value === 'form') {
    const detail = buildServerDetailFromForm(form)
    const result = validateServerDetail(detail)
    const firstError = getFirstValidationError(result)
    if (firstError) {
      return {
        scheme: 'warning',
        message: `Not ready: ${firstError}`,
      }
    }

    return {
      scheme: 'success',
      message: 'Ready to submit',
    }
  }

  if (inputMode.value === 'url') {
    const {jsonUrlInput} = getPrivateServerFieldInputs(form)
    if (!jsonUrlInput) return null

    const urlValue = jsonUrlInput.value.trim()
    if (urlValue.length === 0) {
      return {
        scheme: 'warning',
        message: 'Not ready: missing JSON URL',
      }
    }

    const currentUrlFetchState = getPrivateServerUrlFetchState(form)

    if (currentUrlFetchState.state === 'loading') {
      return {
        scheme: 'warning',
        message: 'Not ready: loading server JSON',
      }
    }

    if (currentUrlFetchState.state === 'error') {
      return {
        scheme: 'warning',
        message: currentUrlFetchState.message || getPrivateServerUrlFetchFailureMessage(),
      }
    }

    if (currentUrlFetchState.state !== 'success') {
      return {
        scheme: 'warning',
        message: getPrivateServerUrlFetchFailureMessage(),
      }
    }

    return {
      scheme: 'success',
      message: 'Ready to submit',
    }
  }

  if (inputMode.value !== 'json') return null

  const rawJsonInput = form.querySelector<HTMLTextAreaElement>('textarea[name="private_server[raw_json]"]')
  if (!rawJsonInput) return null

  if (rawJsonInput.value.trim().length === 0) {
    return {
      scheme: 'warning',
      message: 'Not ready: missing server JSON',
    }
  }

  const validationError = validatePrivateServerRawJsonForUI(rawJsonInput.value)
  if (validationError) {
    return {
      scheme: 'warning',
      message: validationError,
    }
  }

  return {
    scheme: 'success',
    message: 'Ready to submit',
  }
}

function validatePrivateServerFormBeforeSubmit(form: HTMLFormElement): string | null {
  const validationStatus = getPrivateServerValidationStatus(form)
  if (!validationStatus || validationStatus.scheme === 'success') return null
  return validationStatus.message
}

function updatePrivateServerValidationUI(form: HTMLFormElement): void {
  const validationStatus = getPrivateServerValidationStatus(form)

  const dialogBody = form.closest('[data-view-component]')
  const inputMode =
    form.querySelector<HTMLInputElement>('.js-private-server-input-mode')?.value ||
    dialogBody?.querySelector<HTMLInputElement>('.js-private-server-input-mode')?.value ||
    null
  if (inputMode !== 'url') {
    setPrivateServerUrlNamePreview(form, null)
  }
  setPrivateServerValidationStatus(form, validationStatus)
  setPrivateServerSubmitDisabled(form, validationStatus?.scheme === 'warning')
}

function attachPrivateServerRealtimeValidation(form: HTMLFormElement): void {
  if (form.getAttribute('data-private-server-realtime-validation-attached') === 'true') return

  const {rawJsonInput, rootFieldInputs, jsonUrlInput} = getPrivateServerFieldInputs(form)

  rawJsonInput?.addEventListener('input', () => {
    writeFormStateFromRawJson(form)
    updatePrivateServerValidationUI(form)
  })

  for (const input of rootFieldInputs) {
    input.addEventListener('input', () => {
      writeRawJsonFromFormState(form)
      updatePrivateServerValidationUI(form)
    })
  }

  jsonUrlInput?.addEventListener('input', () => {
    const existingTimer = privateServerUrlInputTimers.get(form)
    if (existingTimer) clearTimeout(existingTimer)

    const timer = setTimeout(() => {
      void (async () => {
        await syncPrivateServerFromJsonUrl(form)
        updatePrivateServerValidationUI(form)
      })()
    }, 400)
    privateServerUrlInputTimers.set(form, timer)
  })

  form.setAttribute('data-private-server-realtime-validation-attached', 'true')
}

function getPanelIdFromLink(link: HTMLAnchorElement): string | null {
  if (link.hash) {
    return link.hash.startsWith('#') ? link.hash.slice(1) : link.hash
  }

  const href = link.getAttribute('href')
  if (!href) return null
  return href.startsWith('#') ? href.slice(1) : href
}

function updateSegmentedControlSelectedState(container: Element | null, link: HTMLAnchorElement): void {
  const segmentedControl = container?.querySelector('segmented-control')
  if (!segmentedControl) return

  const allItems = segmentedControl.querySelectorAll('li.SegmentedControl-item')
  for (const item of allItems) {
    item.classList.remove('SegmentedControl-item--selected')
    item.querySelector('[aria-current]')?.removeAttribute('aria-current')
  }

  const clickedItem = link.closest('li.SegmentedControl-item')
  clickedItem?.classList.add('SegmentedControl-item--selected')
  link.setAttribute('aria-current', 'true')
}

// SegmentedControl toggle handler - registered at module load time
on('click', '.js-mcp-toggle-test a', function (event) {
  event.preventDefault()

  const link = event.currentTarget as HTMLAnchorElement
  const panelId = getPanelIdFromLink(link)
  if (!panelId) return

  // Find the container that holds both the toggle and panels
  const container = link.closest('.js-mcp-toggle-test')
  const dialogBody = container?.closest('[data-view-component]') || container?.parentElement

  // Private server form/json toggle
  if (container?.getAttribute('data-private-server-toggle') === 'true') {
    const formPanel = dialogBody?.querySelector<HTMLElement>('[data-private-server-panel="form"]')
    const jsonPanel = dialogBody?.querySelector<HTMLElement>('[data-private-server-panel="json"]')
    const urlPanel = dialogBody?.querySelector<HTMLElement>('[data-private-server-panel="url"]')
    const form = dialogBody?.querySelector<HTMLFormElement>('form[data-private-server-form="true"]')
    const inputMode =
      form?.querySelector<HTMLInputElement>('.js-private-server-input-mode') ||
      dialogBody?.querySelector<HTMLInputElement>('.js-private-server-input-mode') ||
      null

    if (formPanel && jsonPanel) {
      const showJson = panelId.endsWith('-panel-json')
      const showForm = panelId.endsWith('-panel-form')
      const showUrl = panelId.endsWith('-panel-url')
      if (showJson || showForm || showUrl) {
        // Read previous mode before switching
        const previousMode = inputMode?.value || 'form'

        formPanel.hidden = !showForm
        jsonPanel.hidden = !showJson
        if (urlPanel) urlPanel.hidden = !showUrl
        if (inputMode) {
          if (showJson) inputMode.value = 'json'
          if (showForm) inputMode.value = 'form'
          if (showUrl) inputMode.value = 'url'
        }

        if (form) {
          // Abort any in-flight URL fetch when switching away from the URL tab
          // to prevent stale responses from overwriting user edits.
          if (!showUrl) {
            privateServerUrlFetchControllers.get(form)?.abort()
          }

          if (showForm) {
            writeFormStateFromRawJson(form)
          }

          if (showJson && previousMode === 'form') {
            // Only rebuild raw JSON from form state when coming from Form mode.
            // When coming from URL mode, rawJsonInput already has the full fetched JSON.
            writeRawJsonFromFormState(form)
          }

          if (showUrl) {
            void (async () => {
              await syncPrivateServerFromJsonUrl(form)
              updatePrivateServerValidationUI(form)
            })()
          }

          updatePrivateServerValidationUI(form)
        }
      }
    }

    updateSegmentedControlSelectedState(container, link)
    return
  }

  // Toggle panels - search within the dialog context
  const externalPanel = dialogBody?.querySelector<HTMLElement>(`#${PANEL_IDS.EXTERNAL}`)
  const githubPanel = dialogBody?.querySelector<HTMLElement>(`#${PANEL_IDS.GITHUB}`)

  if (externalPanel) externalPanel.hidden = panelId !== PANEL_IDS.EXTERNAL
  if (githubPanel) githubPanel.hidden = panelId !== PANEL_IDS.GITHUB

  updateSegmentedControlSelectedState(container, link)

  // Update hidden input - only set for known panel IDs
  const input = container?.querySelector<HTMLInputElement>('.js-mcp-type-value')
  if (input) {
    if (panelId === PANEL_IDS.EXTERNAL) {
      input.value = 'external'
    } else if (panelId === PANEL_IDS.GITHUB) {
      input.value = 'github'
    }
  }

  // Toggle registry URL fields so only the active panel's URL submits
  const externalUrl = dialogBody?.querySelector<HTMLInputElement>('input.js-mcp-external-url')
  const githubUrl = dialogBody?.querySelector<HTMLInputElement>('input.js-mcp-github-url')
  if (externalUrl instanceof HTMLInputElement) externalUrl.disabled = panelId !== PANEL_IDS.EXTERNAL
  if (githubUrl instanceof HTMLInputElement) githubUrl.disabled = panelId !== PANEL_IDS.GITHUB
})

on('submit', 'form[data-private-server-form="true"]', function (event) {
  const form = event.currentTarget as HTMLFormElement
  updatePrivateServerValidationUI(form)

  const errorMessage = validatePrivateServerFormBeforeSubmit(form)

  if (errorMessage) {
    event.preventDefault()
    return
  }
})

on('change', 'form[data-private-server-form="true"] textarea[name="private_server[raw_json]"]', function (event) {
  const textarea = event.currentTarget as HTMLTextAreaElement
  const form = textarea.closest('form[data-private-server-form="true"]')
  if (!(form instanceof HTMLFormElement)) return

  clearPrivateServerJsonUrl(form)
  writeFormStateFromRawJson(form)
  updatePrivateServerValidationUI(form)
})

on('change', 'form[data-private-server-form="true"] input[name="private_server[json_url]"]', function (event) {
  const input = event.currentTarget as HTMLInputElement
  const form = input.closest('form[data-private-server-form="true"]')
  if (!(form instanceof HTMLFormElement)) return

  void (async () => {
    await syncPrivateServerFromJsonUrl(form)
    updatePrivateServerValidationUI(form)
  })()
})

on('change', 'form[data-private-server-form="true"] [data-private-server-root-field]', function (event) {
  const input = event.currentTarget as HTMLElement
  const form = input.closest('form[data-private-server-form="true"]')
  if (!(form instanceof HTMLFormElement)) return

  clearPrivateServerJsonUrl(form)
  writeRawJsonFromFormState(form)
  updatePrivateServerValidationUI(form)
})

// Custom event: triggered by packages-remotes-table.ts after table mutations
document.addEventListener('private-server:sync-json', function (event) {
  const form = (event.target as HTMLElement)?.closest('form[data-private-server-form="true"]')
  if (form instanceof HTMLFormElement) {
    clearPrivateServerJsonUrl(form)
    writeRawJsonFromFormState(form)
    updatePrivateServerValidationUI(form)
  }
})

for (const form of document.querySelectorAll<HTMLFormElement>('form[data-private-server-form="true"]')) {
  attachPrivateServerRealtimeValidation(form)
  const inputMode = form.querySelector<HTMLInputElement>('.js-private-server-input-mode')?.value
  if (inputMode === 'url') {
    void (async () => {
      await syncPrivateServerFromJsonUrl(form)
      updatePrivateServerValidationUI(form)
    })()
    continue
  }

  // If raw JSON is prepopulated (e.g. from URL import redirect), sync form fields
  const {rawJsonInput} = getPrivateServerFieldInputs(form)
  if (rawJsonInput && rawJsonInput.value.trim().length > 0) {
    writeFormStateFromRawJson(form)
  }

  updatePrivateServerValidationUI(form)
}
