import {on} from 'delegated-events'
import {verifiedFetch} from '@github-ui/verified-fetch'

let debounceTimer: ReturnType<typeof setTimeout> | null = null
let searchController: AbortController | null = null
let newOrgIds: number[] = []
let lastSelectedValue: string | null = null
// eslint-disable-next-line i18n-text/no-en
const ADD_BTN_DEFAULT_TEXT = 'Add organizations'

function resetAddButton() {
  const btn = document.querySelector<HTMLButtonElement>('.js-add-organizations-btn')
  if (btn) {
    btn.textContent = ADD_BTN_DEFAULT_TEXT
    btn.disabled = true
    btn.removeAttribute('data-disable-with')
  }
}

function resetPicker(resetProperty: boolean = false) {
  const picker = document.querySelector<HTMLElement>('copilot-custom-property-picker')
  if (!picker) return

  const resultsContainer = picker.querySelector<HTMLElement>('.js-custom-property-results')
  if (resultsContainer) resultsContainer.hidden = true

  resetAddButton()
  newOrgIds = []
  lastSelectedValue = null

  // Reset all value panels
  for (const container of picker.querySelectorAll<HTMLElement>('.js-custom-property-value')) {
    container.hidden = true
    const valuePanel = container.querySelector<HTMLElement>('.js-custom-property-value-select-panel')
    if (valuePanel) {
      for (const selected of valuePanel.querySelectorAll('[aria-selected="true"]')) {
        selected.setAttribute('aria-selected', 'false')
      }
      const valueLabel = valuePanel.querySelector<HTMLElement>('.Button-label')
      if (valueLabel) {
        // eslint-disable-next-line i18n-text/no-en
        valueLabel.textContent = 'Select a value'
      }
    }
    const textInput = container.querySelector<HTMLInputElement>('input[type="text"]')
    if (textInput) textInput.value = ''
  }

  if (resetProperty) {
    const propertyPanel = picker.querySelector<HTMLElement>('.js-custom-property')
    if (propertyPanel) {
      for (const selected of propertyPanel.querySelectorAll('[aria-selected="true"]')) {
        selected.setAttribute('aria-selected', 'false')
      }
      const invokerLabel = propertyPanel.querySelector<HTMLElement>('.Button-label')
      if (invokerLabel) {
        const originalText = propertyPanel.querySelector<HTMLElement>('dialog h1')?.textContent?.trim()
        if (originalText) {
          invokerLabel.textContent = originalText
        }
      }
    }
  }
}

async function searchOrganizations() {
  const picker = document.querySelector<HTMLElement>('copilot-custom-property-picker')
  if (!picker) return

  const searchUrl = picker.getAttribute('data-search-url')
  if (!searchUrl) return

  const propertyPanel = picker.querySelector<HTMLElement>('.js-custom-property')
  const selectedPropertyItem = propertyPanel?.querySelector('[aria-selected="true"] .ActionListItem-label')
  const propertyName = selectedPropertyItem?.textContent?.trim()
  if (!propertyName) return

  const visibleValueContainer = picker.querySelector<HTMLElement>('.js-custom-property-value:not([hidden])')
  if (!visibleValueContainer) return

  let value: string | undefined
  const textInput = visibleValueContainer.querySelector<HTMLInputElement>('input[type="text"]')
  if (textInput) {
    value = textInput.value.trim()
  } else {
    const valueItem = visibleValueContainer.querySelector('[aria-selected="true"] .ActionListItem-label')
    value = valueItem?.textContent?.trim()
  }
  if (!value) return

  const resultsContainer = picker.querySelector<HTMLElement>('.js-custom-property-results')
  const loadingEl = picker.querySelector<HTMLElement>('.js-custom-property-results-loading')
  const listEl = picker.querySelector<HTMLElement>('.js-custom-property-results-list')
  const emptyEl = picker.querySelector<HTMLElement>('.js-custom-property-results-empty')
  const itemsEl = picker.querySelector<HTMLElement>('.js-custom-property-results-items')
  if (!resultsContainer || !loadingEl || !listEl || !emptyEl || !itemsEl) return

  resultsContainer.hidden = false
  loadingEl.hidden = false
  listEl.hidden = true
  emptyEl.hidden = true
  resetAddButton()

  const url = new URL(searchUrl, window.location.origin)
  url.searchParams.set('property_name', propertyName)
  url.searchParams.set('value', value)

  // Cancel any in-flight search to prevent stale results from rendering out of order
  if (searchController) searchController.abort()
  searchController = new AbortController()

  try {
    const response = await verifiedFetch(url.toString(), {
      headers: {Accept: 'application/json'},
      signal: searchController.signal,
    })
    const data = await response.json()

    loadingEl.hidden = true
    itemsEl.textContent = ''

    if (data.organizations && data.organizations.length > 0) {
      const count = data.organizations.length
      const alreadyCount = data.organizations.filter(
        (o: {coding_agent_enabled: boolean}) => o.coding_agent_enabled,
      ).length

      const matchCountEl = picker.querySelector<HTMLElement>('.js-custom-property-results-match-count')
      if (matchCountEl) {
        matchCountEl.textContent = `${count} organization${count === 1 ? '' : 's'} match${count === 1 ? 'es' : ''}`
      }
      const alreadyCountEl = picker.querySelector<HTMLElement>('.js-custom-property-results-already-selected-count')
      if (alreadyCountEl) {
        alreadyCountEl.textContent = alreadyCount > 0 ? `${alreadyCount} already selected` : ''
      }
      const addableCount = count - alreadyCount
      newOrgIds = data.organizations
        .filter((o: {id: number; coding_agent_enabled: boolean}) => !o.coding_agent_enabled)
        .map((o: {id: number}) => o.id)

      const addBtn = document.querySelector<HTMLButtonElement>('.js-add-organizations-btn')
      if (addBtn) {
        if (addableCount > 0) {
          // eslint-disable-next-line i18n-text/no-en
          const addText = `Add ${addableCount} organization${addableCount === 1 ? '' : 's'}`
          addBtn.textContent = addText
          addBtn.setAttribute('data-disable-with', addText)
          addBtn.disabled = false
        } else {
          addBtn.disabled = true
        }
      }
      // Render each organization as a list item with avatar, name, and "Already selected" badge if applicable
      for (const org of data.organizations) {
        const li = document.createElement('li')
        li.className = `d-flex flex-items-center width-full py-2 px-2 border-top${org.coding_agent_enabled ? ' color-fg-muted' : ''}`

        const img = document.createElement('img')
        img.src = org.avatar_url
        img.alt = ''
        img.className = 'avatar avatar--square mr-2'
        img.width = 24
        img.height = 24
        if (org.coding_agent_enabled) img.style.opacity = '0.6'
        li.appendChild(img)

        const strong = document.createElement('strong')
        strong.className = 'css-truncate-target width-fit flex-auto'
        strong.textContent = org.login
        li.appendChild(strong)

        if (org.coding_agent_enabled) {
          const badge = document.createElement('span')
          badge.className = 'text-small color-fg-muted'
          // eslint-disable-next-line i18n-text/no-en
          badge.textContent = 'Already selected'
          li.appendChild(badge)
        }

        itemsEl.appendChild(li)
      }
      const firstItem = itemsEl.querySelector('li')
      if (firstItem) firstItem.classList.remove('border-top')

      listEl.hidden = false
    } else {
      emptyEl.hidden = false
      const addBtn = document.querySelector<HTMLButtonElement>('.js-add-organizations-btn')
      if (addBtn) addBtn.disabled = true
    }
  } catch {
    loadingEl.hidden = true
    emptyEl.hidden = false
  }
}

// Listen for custom property selection
on('click', '.js-custom-property-item', function (event) {
  const item = event.currentTarget as HTMLElement
  const picker = item.closest('copilot-custom-property-picker')
  if (!picker) return

  const selectedProperty = item.getAttribute('data-value')

  // If the same property is already shown, don't reset anything
  const currentlyVisible = picker.querySelector<HTMLElement>('.js-custom-property-value:not([hidden])')
  if (
    currentlyVisible &&
    selectedProperty &&
    currentlyVisible.getAttribute('data-property-name') === selectedProperty
  ) {
    return
  }

  // New property selection — reset value panels and hide results
  resetPicker()

  // Show the matching value select
  if (selectedProperty) {
    const matchingContainer = picker.querySelector<HTMLElement>(
      `.js-custom-property-value[data-property-name="${CSS.escape(selectedProperty)}"]`,
    )
    if (matchingContainer) {
      matchingContainer.hidden = false
    }
  }
})

// Listen for custom property value selection, selecting a value will trigger a search for organizations with that property value
on('click', '.js-custom-property-value-item', function (event) {
  const item = event.currentTarget as HTMLElement
  const selectedValue = item.getAttribute('data-value') || ''

  // Skip duplicate search if the same value is already selected
  if (selectedValue && selectedValue === lastSelectedValue) return
  lastSelectedValue = selectedValue

  searchOrganizations()
})

// Reset picker state when the custom property dialog is closed
on('click', '[data-close-dialog-id="copilot-coding-agent-custom-property-dialog"]', function () {
  const picker = document.querySelector('copilot-custom-property-picker')
  if (!picker) return

  resetPicker(true)
})

// Populate hidden inputs with the selected org IDs before the form submits natively
on('submit', '.js-custom-property-form', function (event) {
  const form = event.currentTarget as HTMLFormElement
  if (newOrgIds.length === 0) {
    event.preventDefault()
    return
  }

  const idsContainer = form.querySelector<HTMLElement>('.js-custom-property-org-ids')
  if (idsContainer) {
    idsContainer.textContent = ''
    for (const id of newOrgIds) {
      const input = document.createElement('input')
      input.type = 'hidden'
      input.name = 'newly_enabled_organization_ids[]'
      input.value = String(id)
      idsContainer.appendChild(input)
    }
  }
})

// This listener is for text type custom property, we want to debounce the input and only trigger org search when user stops typing for 500ms
document.addEventListener('input', function (event) {
  if (!(event.target instanceof HTMLInputElement)) return
  if (!event.target.classList.contains('js-custom-property-value-input')) return

  if (debounceTimer) clearTimeout(debounceTimer)
  debounceTimer = setTimeout(() => searchOrganizations(), 500)
})
