/**
 * Handles the "Create server" dialog's URL fetch + validation flow.
 *
 * Flow:
 * 1. User enters a URL and clicks "Load"
 * 2. URL is validated and fetched (via proxy endpoint)
 * 3. On success: shows server name preview, enables "Create" button
 * 4. Clicking "Create" navigates to the new-server form page with prepopulated JSON
 */

import {on} from 'delegated-events'
import {getEmbeddedServerJsonFromUrl} from './utils'

const SELECTORS = {
  dialog: '[data-create-server-dialog]',
  urlInput: '[data-create-server-url-input]',
  loadButton: '[data-create-server-url-load]',
  createButton: '[data-create-server-url-create]',
  errorMessage: '[data-create-server-url-error]',
  loading: '[data-create-server-url-loading]',
  success: '[data-create-server-url-success]',
  previewName: '[data-create-server-url-preview-name]',
} as const

let validatedPayload: Record<string, unknown> | null = null
let currentFetchController: AbortController | null = null

function getDialogContainer(el: Element): Element {
  return el.closest(SELECTORS.dialog) || document.documentElement
}

function clearFeedback(container: Element): void {
  const errorEl = container.querySelector<HTMLElement>(SELECTORS.errorMessage)
  const loadingEl = container.querySelector<HTMLElement>(SELECTORS.loading)
  const successEl = container.querySelector<HTMLElement>(SELECTORS.success)

  if (errorEl) {
    errorEl.textContent = ''
    errorEl.hidden = true
  }
  if (loadingEl) loadingEl.hidden = true
  if (successEl) successEl.hidden = true
}

function showError(container: Element, message: string): void {
  clearFeedback(container)
  const errorEl = container.querySelector<HTMLElement>(SELECTORS.errorMessage)
  if (errorEl) {
    errorEl.textContent = message
    errorEl.hidden = false
  }
}

function showSuccess(container: Element, payload: Record<string, unknown>): void {
  clearFeedback(container)

  const server =
    payload.server && typeof payload.server === 'object' && !Array.isArray(payload.server)
      ? (payload.server as Record<string, unknown>)
      : payload

  const name = typeof server.name === 'string' ? server.name : 'Unknown server'

  const successEl = container.querySelector<HTMLElement>(SELECTORS.success)
  const previewNameEl = container.querySelector<HTMLElement>(SELECTORS.previewName)

  if (successEl) successEl.hidden = false
  if (previewNameEl) previewNameEl.textContent = name

  validatedPayload = payload

  const createBtn = container.querySelector<HTMLButtonElement>(SELECTORS.createButton)
  if (createBtn) createBtn.disabled = false
}

function resetCreateButton(container: Element): void {
  validatedPayload = null
  const createBtn = container.querySelector<HTMLButtonElement>(SELECTORS.createButton)
  if (createBtn) createBtn.disabled = true
}

function normalizePayload(parsed: unknown): Record<string, unknown> | null {
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return null

  const topLevel = parsed as Record<string, unknown>
  const serverCandidate =
    topLevel.server && typeof topLevel.server === 'object' && !Array.isArray(topLevel.server)
      ? (topLevel.server as Record<string, unknown>)
      : topLevel

  const name = typeof serverCandidate.name === 'string' ? serverCandidate.name.trim() : ''
  if (name.length === 0) return null

  const result = {...serverCandidate}
  result.name = name
  if (typeof result.version !== 'string' || result.version.trim().length === 0) {
    result.version = '1.0.0'
  } else {
    result.version = result.version.trim()
  }

  return result
}

async function fetchAndValidate(container: Element, rawUrl: string): Promise<void> {
  // Abort any previous in-flight request to prevent stale responses from overwriting newer ones
  if (currentFetchController) currentFetchController.abort()
  const controller = new AbortController()
  currentFetchController = controller

  try {
    let url: URL
    try {
      url = new URL(rawUrl, window.location.origin)
    } catch {
      throw new Error('Invalid URL. Please enter a full https:// URL.')
    }

    if (url.protocol !== 'https:') {
      throw new Error('URL must use HTTPS.')
    }

    // Check for embedded server_json param first
    const inlineJson = getEmbeddedServerJsonFromUrl(rawUrl)
    let payload: Record<string, unknown> | null

    if (inlineJson) {
      try {
        const parsed = JSON.parse(inlineJson)
        payload = normalizePayload(parsed)
        if (!payload) {
          throw new Error('Invalid server JSON in URL parameter.')
        }
      } catch (e) {
        if (e instanceof SyntaxError) {
          throw new Error('Invalid JSON in server_json URL parameter.')
        }
        throw e
      }
    } else {
      // Fetch via server-side proxy
      const fetchPath = container.closest(SELECTORS.dialog)?.getAttribute('data-fetch-server-json-path')
      if (!fetchPath) {
        throw new Error('Configuration error: missing fetch path.')
      }

      const endpoint = `${fetchPath}?url=${encodeURIComponent(rawUrl)}`
      const response = await fetch(endpoint, {
        headers: {Accept: 'application/json'},
        signal: controller.signal,
      })

      if (!response.ok) {
        // eslint-disable-next-line i18n-text/no-en
        let errorMessage = `Unable to fetch JSON (${response.status})`
        try {
          const errorPayload = (await response.json()) as {error?: string}
          if (typeof errorPayload?.error === 'string' && errorPayload.error.length > 0) {
            errorMessage = errorPayload.error
          }
        } catch {
          /* use default */
        }
        throw new Error(errorMessage)
      }

      const responseData = await response.json()
      payload = normalizePayload(responseData)
      if (!payload) {
        throw new Error('Unable to load server JSON: response did not contain a valid server definition.')
      }
    }

    if (controller.signal.aborted) return
    showSuccess(container, payload)
  } catch (error) {
    if (controller.signal.aborted) return
    showError(container, error instanceof Error ? error.message : 'Failed to fetch server JSON.')
  }
}

// Load button click (manual trigger)
on('click', SELECTORS.loadButton, function (event) {
  const loadBtn = event.currentTarget as HTMLButtonElement
  const container = getDialogContainer(loadBtn)
  const urlInput = container.querySelector<HTMLInputElement>(SELECTORS.urlInput)
  if (!urlInput) return

  const rawUrl = urlInput.value.trim()
  if (rawUrl.length === 0) {
    // eslint-disable-next-line i18n-text/no-en
    showError(container, 'Please enter a URL.')
    return
  }

  // Cancel any pending auto-validate to prevent concurrent fetches
  if (autoValidateTimer) {
    clearTimeout(autoValidateTimer)
    autoValidateTimer = null
  }

  clearFeedback(container)
  resetCreateButton(container)

  const loadingEl = container.querySelector<HTMLElement>(SELECTORS.loading)
  if (loadingEl) loadingEl.hidden = false
  loadBtn.disabled = true

  void (async () => {
    await fetchAndValidate(container, rawUrl)
    loadBtn.disabled = false
  })()
})

// Create button click (navigates to form page with prepopulated JSON)
on('click', SELECTORS.createButton, function (event) {
  const createBtn = event.currentTarget as HTMLButtonElement
  if (createBtn.disabled || !validatedPayload) return

  const container = getDialogContainer(createBtn)

  // The form lives as a sibling of the dialog container (inside the dialog body),
  // so search from the parent element to find it.
  const scope = container.parentElement ?? container
  const form = scope.querySelector<HTMLFormElement>('[data-create-server-post-form]')
  const field = form?.querySelector<HTMLInputElement>('[data-create-server-json-field]')
  if (!form || !field) return

  field.value = JSON.stringify(validatedPayload)
  form.submit()
})

// Auto-validate on URL input change (debounced)
let autoValidateTimer: ReturnType<typeof setTimeout> | null = null

on('change', SELECTORS.urlInput, function (event) {
  const input = event.currentTarget as HTMLInputElement
  const container = getDialogContainer(input)

  if (autoValidateTimer) {
    clearTimeout(autoValidateTimer)
    autoValidateTimer = null
  }

  const rawUrl = input.value.trim()
  if (rawUrl.length === 0) {
    // Abort any in-flight validation so a late response can't re-enable the
    // Create button for an empty URL.
    if (currentFetchController) currentFetchController.abort()
    clearFeedback(container)
    resetCreateButton(container)
    return
  }

  clearFeedback(container)
  resetCreateButton(container)

  const loadingEl = container.querySelector<HTMLElement>(SELECTORS.loading)
  if (loadingEl) loadingEl.hidden = false

  autoValidateTimer = setTimeout(() => {
    void (async () => {
      await fetchAndValidate(container, rawUrl)
    })()
  }, 300)
})
