import {on} from 'delegated-events'
import {parseHTML} from '@github-ui/parse-html'
import {escapeHtml} from './templates'

// ─── Helpers ───────────────────────────────────────────────────────────────────

function getForm(el: HTMLElement): HTMLFormElement | null {
  return el.closest('form[data-private-server-form="true"]')
}

function syncFormJson(form: HTMLFormElement): void {
  // Trigger the existing form→JSON sync from segmented-control.ts
  form.dispatchEvent(new CustomEvent('private-server:sync-json', {bubbles: true}))
}

function updateEmptyStates(form: HTMLFormElement): void {
  const pkgList = form.querySelector('[data-private-server-packages-list]')
  const pkgEmpty = form.querySelector<HTMLElement>('[data-private-server-packages-empty]')
  const pkgCount = form.querySelector<HTMLElement>('[data-private-server-packages-count]')
  const pkgChildCount = pkgList ? pkgList.children.length : 0
  if (pkgEmpty) pkgEmpty.hidden = pkgChildCount > 0
  if (pkgCount) pkgCount.textContent = String(pkgChildCount)

  const remoteList = form.querySelector('[data-private-server-remotes-list]')
  const remoteEmpty = form.querySelector<HTMLElement>('[data-private-server-remotes-empty]')
  const remoteCount = form.querySelector<HTMLElement>('[data-private-server-remotes-count]')
  const remoteChildCount = remoteList ? remoteList.children.length : 0
  if (remoteEmpty) remoteEmpty.hidden = remoteChildCount > 0
  if (remoteCount) remoteCount.textContent = String(remoteChildCount)
}

// ─── Package table row helpers ─────────────────────────────────────────────────

const PACKAGE_FIELDS = ['registryType', 'identifier', 'version', 'transport.type', 'transport.url', 'runtimeHint']

function buildPackageRow(values: Record<string, string>): HTMLElement {
  const row = document.createElement('div')
  row.setAttribute('data-private-server-package-entry', '')
  row.className = 'Box-row py-2 px-3'

  const registryType = values['registryType'] || 'npm'
  const identifier = values['identifier'] || ''
  const version = values['version'] || ''
  const transportType = values['transport.type'] || 'stdio'
  const transportUrl = values['transport.url'] || ''
  const runtimeHint = values['runtimeHint'] || ''

  // Effective values (with defaults applied) so the displayed row and the
  // serialized hidden inputs stay consistent.
  const defaultedValues: Record<string, string> = {
    registryType,
    identifier,
    version,
    'transport.type': transportType,
    'transport.url': transportUrl,
    runtimeHint,
  }

  row.appendChild(
    parseHTML(
      document,
      `
    <div class="d-flex flex-row width-full flex-items-center">
      <div class="col-2 text-small">${escapeHtml(registryType)}</div>
      <div class="col-3 text-small text-mono text-truncate">${escapeHtml(identifier)}</div>
      <div class="col-2 text-small">${escapeHtml(version)}</div>
      <div class="col-2 text-small">${escapeHtml(transportType)}${transportUrl ? ` (${escapeHtml(truncate(transportUrl, 20))})` : ''}</div>
      <div class="col-2 text-small">${escapeHtml(runtimeHint) || '—'}</div>
      <div class="col-1 text-right">
        <button type="button" class="btn-octicon" data-private-server-edit-package aria-label="Edit package">
          <svg class="octicon octicon-pencil" viewBox="0 0 16 16" width="16" height="16"><path d="M11.013 1.427a1.75 1.75 0 0 1 2.474 0l1.086 1.086a1.75 1.75 0 0 1 0 2.474l-8.61 8.61c-.21.21-.47.364-.756.445l-3.251.93a.75.75 0 0 1-.927-.928l.929-3.25c.081-.286.235-.547.445-.758l8.61-8.61Zm.176 4.823L9.75 4.81l-6.286 6.287a.253.253 0 0 0-.064.108l-.558 1.953 1.953-.558a.253.253 0 0 0 .108-.064l6.286-6.286Z"></path></svg>
        </button>
        <button type="button" class="btn-octicon color-fg-danger" data-private-server-remove-entry aria-label="Remove package">
          <svg class="octicon octicon-trash" viewBox="0 0 16 16" width="16" height="16"><path d="M11 1.75V3h2.25a.75.75 0 0 1 0 1.5H2.75a.75.75 0 0 1 0-1.5H5V1.75C5 .784 5.784 0 6.75 0h2.5C10.216 0 11 .784 11 1.75ZM6.5 1.75v1.5h3v-1.5a.25.25 0 0 0-.25-.25h-2.5a.25.25 0 0 0-.25.25ZM3.613 5.5l.614 8.571A1.75 1.75 0 0 0 5.975 15.5h4.05a1.75 1.75 0 0 0 1.748-1.429L12.387 5.5Z"></path></svg>
        </button>
      </div>
    </div>
  `,
    ),
  )

  // Hidden inputs for form serialization (buildServerDetailFromForm reads these)
  for (const field of PACKAGE_FIELDS) {
    const input = document.createElement('input')
    input.type = 'hidden'
    input.setAttribute('data-private-server-package-field', field)
    input.value = defaultedValues[field] || ''
    row.appendChild(input)
  }

  return row
}

// ─── Remote table row helpers ──────────────────────────────────────────────────

const REMOTE_FIELDS = ['type', 'url']

function buildRemoteRow(values: Record<string, string>): HTMLElement {
  const row = document.createElement('div')
  row.setAttribute('data-private-server-remote-entry', '')
  row.className = 'Box-row py-2 px-3'

  const type = values['type'] || 'streamable-http'
  const url = values['url'] || ''

  // Effective values (with defaults applied) so the displayed row and the
  // serialized hidden inputs stay consistent.
  const defaultedValues: Record<string, string> = {type, url}

  row.appendChild(
    parseHTML(
      document,
      `
    <div class="d-flex flex-row width-full flex-items-center">
      <div class="col-3 text-small">${escapeHtml(type)}</div>
      <div class="col-8 text-small text-mono text-truncate">${escapeHtml(truncate(url, 60))}</div>
      <div class="col-1 text-right">
        <button type="button" class="btn-octicon" data-private-server-edit-remote aria-label="Edit remote">
          <svg class="octicon octicon-pencil" viewBox="0 0 16 16" width="16" height="16"><path d="M11.013 1.427a1.75 1.75 0 0 1 2.474 0l1.086 1.086a1.75 1.75 0 0 1 0 2.474l-8.61 8.61c-.21.21-.47.364-.756.445l-3.251.93a.75.75 0 0 1-.927-.928l.929-3.25c.081-.286.235-.547.445-.758l8.61-8.61Zm.176 4.823L9.75 4.81l-6.286 6.287a.253.253 0 0 0-.064.108l-.558 1.953 1.953-.558a.253.253 0 0 0 .108-.064l6.286-6.286Z"></path></svg>
        </button>
        <button type="button" class="btn-octicon color-fg-danger" data-private-server-remove-entry aria-label="Remove remote">
          <svg class="octicon octicon-trash" viewBox="0 0 16 16" width="16" height="16"><path d="M11 1.75V3h2.25a.75.75 0 0 1 0 1.5H2.75a.75.75 0 0 1 0-1.5H5V1.75C5 .784 5.784 0 6.75 0h2.5C10.216 0 11 .784 11 1.75ZM6.5 1.75v1.5h3v-1.5a.25.25 0 0 0-.25-.25h-2.5a.25.25 0 0 0-.25.25ZM3.613 5.5l.614 8.571A1.75 1.75 0 0 0 5.975 15.5h4.05a1.75 1.75 0 0 0 1.748-1.429L12.387 5.5Z"></path></svg>
        </button>
      </div>
    </div>
  `,
    ),
  )

  for (const field of REMOTE_FIELDS) {
    const input = document.createElement('input')
    input.type = 'hidden'
    input.setAttribute('data-private-server-remote-field', field)
    input.value = defaultedValues[field] || ''
    row.appendChild(input)
  }

  return row
}

// ─── Dialog helpers ────────────────────────────────────────────────────────────

function openPrimerDialog(id: string): void {
  const dialog = document.getElementById(id)
  if (dialog && 'show' in dialog && typeof (dialog as {show: () => void}).show === 'function') {
    ;(dialog as {show: () => void}).show()
  }
}

function closePrimerDialog(id: string): void {
  const dialog = document.getElementById(id)
  if (dialog && 'close' in dialog && typeof (dialog as {close: () => void}).close === 'function') {
    ;(dialog as {close: () => void}).close()
  }
}

function getDialogFieldValues(dialog: HTMLElement, attrPrefix: string): Record<string, string> {
  const values: Record<string, string> = {}
  const fields = dialog.querySelectorAll<HTMLInputElement | HTMLSelectElement>(`[${attrPrefix}]`)
  for (const field of fields) {
    const key = field.getAttribute(attrPrefix)
    if (key) values[key] = field.value
  }
  return values
}

function setDialogFieldValues(dialog: HTMLElement, attrPrefix: string, values: Record<string, string>): void {
  const fields = dialog.querySelectorAll<HTMLInputElement | HTMLSelectElement>(`[${attrPrefix}]`)
  for (const field of fields) {
    const key = field.getAttribute(attrPrefix)
    if (key && key in values) {
      field.value = values[key] || ''
      field.dispatchEvent(new Event('change', {bubbles: true}))
    }
  }
}

function resetDialogFields(dialog: HTMLElement, attrPrefix: string): void {
  const fields = dialog.querySelectorAll<HTMLInputElement | HTMLSelectElement>(`[${attrPrefix}]`)
  for (const field of fields) {
    if (field instanceof HTMLSelectElement) {
      field.selectedIndex = 0
    } else {
      field.value = ''
    }
  }
}

// ─── Utilities ─────────────────────────────────────────────────────────────────

function truncate(str: string, max: number): string {
  return str.length > max ? `${str.slice(0, max)}…` : str
}

// ─── State: track which row is being edited ────────────────────────────────────

let editingPackageRow: HTMLElement | null = null
let editingRemoteRow: HTMLElement | null = null

// ─── Package dialog events ─────────────────────────────────────────────────────

// Add Package button — reset dialog fields (Primer opens dialog via data-show-dialog-id)
on('click', '[data-private-server-add-package]', function () {
  const dialog = document.querySelector<HTMLElement>('[data-private-server-package-dialog]')
  if (!dialog) return

  editingPackageRow = null
  const title = document.querySelector('[data-private-server-package-dialog-title]')
  // eslint-disable-next-line i18n-text/no-en
  if (title) title.textContent = 'Add package'
  resetDialogFields(dialog, 'data-private-server-package-dialog-field')

  // Reset transport URL visibility
  const urlContainer = dialog.querySelector<HTMLElement>('[data-private-server-package-dialog-transport-url]')
  if (urlContainer) urlContainer.hidden = true
})

// Open Edit Package dialog
on('click', '[data-private-server-edit-package]', function (event) {
  const btn = event.currentTarget as HTMLElement
  const row = btn.closest<HTMLElement>('[data-private-server-package-entry]')
  if (!row) return

  const dialog = document.querySelector<HTMLElement>('[data-private-server-package-dialog]')
  if (!dialog) return

  editingPackageRow = row
  const title = document.querySelector('[data-private-server-package-dialog-title]')
  // eslint-disable-next-line i18n-text/no-en
  if (title) title.textContent = 'Edit package'

  // Read hidden inputs from row
  const values: Record<string, string> = {}
  for (const field of PACKAGE_FIELDS) {
    const input = row.querySelector<HTMLInputElement>(`[data-private-server-package-field="${field}"]`)
    values[field] = input?.value || ''
  }
  setDialogFieldValues(dialog, 'data-private-server-package-dialog-field', values)

  // Show/hide transport URL
  const urlContainer = dialog.querySelector<HTMLElement>('[data-private-server-package-dialog-transport-url]')
  if (urlContainer) urlContainer.hidden = values['transport.type'] === 'stdio' || !values['transport.type']

  openPrimerDialog('package-form-dialog')
})

// Save Package dialog
on('click', '[data-private-server-package-dialog-save]', function () {
  const dialog = document.querySelector<HTMLElement>('[data-private-server-package-dialog]')
  if (!dialog) return

  const values = getDialogFieldValues(dialog, 'data-private-server-package-dialog-field')

  // Require at least an identifier
  if (!values['identifier']?.trim()) {
    const identifierInput = dialog.querySelector<HTMLInputElement>(
      '[data-private-server-package-dialog-field="identifier"]',
    )
    if (identifierInput) identifierInput.focus()
    return
  }

  const packagesListEl = document.querySelector<HTMLElement>('[data-private-server-packages-list]')
  if (!packagesListEl) return
  const form = getForm(packagesListEl)
  const list = form?.querySelector('[data-private-server-packages-list]')
  if (!list) return

  const newRow = buildPackageRow(values)
  if (editingPackageRow?.isConnected) {
    editingPackageRow.replaceWith(newRow)
  } else {
    // The row being edited was removed before save — append instead of dropping the edits
    list.appendChild(newRow)
  }
  editingPackageRow = null

  closePrimerDialog('package-form-dialog')
  if (form) {
    syncFormJson(form)
    updateEmptyStates(form)
  }
})

// Package transport type toggle in dialog
on('change', '[data-private-server-package-dialog-field="transport.type"]', function (event) {
  const select = event.currentTarget as HTMLSelectElement
  const dialog = select.closest('[data-private-server-package-dialog]')
  const urlContainer = dialog?.querySelector<HTMLElement>('[data-private-server-package-dialog-transport-url]')
  if (urlContainer) urlContainer.hidden = select.value === 'stdio'
})

// ─── Remote dialog events ──────────────────────────────────────────────────────

// Add Remote button — reset dialog fields (Primer opens dialog via data-show-dialog-id)
on('click', '[data-private-server-add-remote]', function () {
  const dialog = document.querySelector<HTMLElement>('[data-private-server-remote-dialog]')
  if (!dialog) return

  editingRemoteRow = null
  const title = document.querySelector('[data-private-server-remote-dialog-title]')
  // eslint-disable-next-line i18n-text/no-en
  if (title) title.textContent = 'Add remote'
  resetDialogFields(dialog, 'data-private-server-remote-dialog-field')
})

// Open Edit Remote dialog
on('click', '[data-private-server-edit-remote]', function (event) {
  const btn = event.currentTarget as HTMLElement
  const row = btn.closest<HTMLElement>('[data-private-server-remote-entry]')
  if (!row) return

  const dialog = document.querySelector<HTMLElement>('[data-private-server-remote-dialog]')
  if (!dialog) return

  editingRemoteRow = row
  const title = document.querySelector('[data-private-server-remote-dialog-title]')
  // eslint-disable-next-line i18n-text/no-en
  if (title) title.textContent = 'Edit remote'

  const values: Record<string, string> = {}
  for (const field of REMOTE_FIELDS) {
    const input = row.querySelector<HTMLInputElement>(`[data-private-server-remote-field="${field}"]`)
    values[field] = input?.value || ''
  }
  setDialogFieldValues(dialog, 'data-private-server-remote-dialog-field', values)
  openPrimerDialog('remote-form-dialog')
})

// Save Remote dialog
on('click', '[data-private-server-remote-dialog-save]', function () {
  const dialog = document.querySelector<HTMLElement>('[data-private-server-remote-dialog]')
  if (!dialog) return

  const values = getDialogFieldValues(dialog, 'data-private-server-remote-dialog-field')

  if (!values['url']?.trim()) {
    const urlInput = dialog.querySelector<HTMLInputElement>('[data-private-server-remote-dialog-field="url"]')
    if (urlInput) urlInput.focus()
    return
  }

  const remotesListEl = document.querySelector<HTMLElement>('[data-private-server-remotes-list]')
  if (!remotesListEl) return
  const form = getForm(remotesListEl)
  const list = form?.querySelector('[data-private-server-remotes-list]')
  if (!list) return

  const newRow = buildRemoteRow(values)
  if (editingRemoteRow?.isConnected) {
    editingRemoteRow.replaceWith(newRow)
  } else {
    // The row being edited was removed before save — append instead of dropping the edits
    list.appendChild(newRow)
  }
  editingRemoteRow = null

  closePrimerDialog('remote-form-dialog')
  if (form) {
    syncFormJson(form)
    updateEmptyStates(form)
  }
})

// ─── Remove entry (packages or remotes) ────────────────────────────────────────

on('click', '[data-private-server-remove-entry]', function (event) {
  const btn = event.currentTarget as HTMLElement
  const entry = btn.closest('[data-private-server-package-entry], [data-private-server-remote-entry]')
  if (!entry) return

  const form = getForm(entry as HTMLElement)
  entry.remove()
  if (form) {
    syncFormJson(form)
    updateEmptyStates(form)
  }
})

// ─── Exported helpers for populatePackageEntries / populateRemoteEntries ────────

export {buildPackageRow, buildRemoteRow, PACKAGE_FIELDS, REMOTE_FIELDS, updateEmptyStates}
